    onMouseDown( e ){
        if(this.persp > 0)return;
        this.raycaster.setFromCamera( this.pointer, camera );
        const intersects = this.raycaster.intersectObjects( this.windows.children )
        if( intersects.length ){
            this.activeWindow = intersects[ 0 ].object
            if( this.activeWindow.d.y * ( 1 - intersects[ 0 ].uv.y ) < 24 ) this.activeWindow.drg = true
            if( 24 / this.activeWindow.d.y > intersects[ 0 ].uv.y ) this.activeWindow.rsy = true
            if( 24 / this.activeWindow.d.x > 1 - intersects[ 0 ].uv.x )  this.activeWindow.rsx = true
            this.oldMouse = new _.Vector2( e.clientX, e.clientY )
            this.windows.children.forEach( w => { if( w.zid > this.activeWindow.zid ) w.zid = w.zid - 1 } )
            this.activeWindow.zid = this.windows.children.length
        }
    }

