    }

    step(t) {
        requestAnimationFrame((t) => this.step(t))
        this.cameraTl += ( this.persp - this.cameraTl ) * 0.05
        this.exposeTl += ( this.expose - this.exposeTl ) * 0.05

        camera.position.x = -800 * this.cameraTl
        camera.position.y = -800 * this.cameraTl

        camera.up= new _.Vector3(0,1-this.cameraTl,this.cameraTl)
        camera.lookAt(new _.Vector3(0,0, 250 ))
        camera.zoom = 1 - 0.2 * this.cameraTl
        camera.updateProjectionMatrix()
        this.windows.children.forEach( c => c.step( this.exposeTl ) )
        this.sim.step( t )
        renderer.setClearColor( new _.Color(0x00000000));
        this.fluid.step( )
        renderer.setClearColor( new _.Color(`rgb(${pal[5][0]},${pal[5][1]},${pal[5][2]})`), 1 );
        this.fluid.updatePosition( new _.Vector2( this.sim.world.agent.op.x, this.sim.world.agent.op.y ) )
        this.particles.step( t )
        this.ascii.updatePosition( new _.Vector2( this.sim.world.agent.op.x, this.sim.world.agent.op.y ) )
        this.ascii.step( t )
        this.windows.children[2].material.uniforms.tex.value = this.particles.readBuffer.texture

        this.windows.children.forEach( w=> {
            w.renderOrder = w.zid
            w.userData.s.position.copy(w.position)
            w.userData.s.position.z = w.position.z + 10
            w.userData.s.scale.set(w.scale.x + 80, w.scale.y + 80, 1 )
            w.userData.s.material.uniforms.dims.value = new _.Vector2( w.scale.x + 80, w.scale.y + 80 )    
            w.userData.s.material.uniforms.op.value = 1 - this.cameraTl
        })
        renderer.render(scene, camera)
    }
}
window.main;
window.onload=()=>{ main = new AppMain() };
